-- ==== 20260924005900_today_feed_scoped_shares.sql
-- Launch safety S8: the Today feed took 3.3 s with 3,000 students (36,000 assignments):
-- joining the assignment_grade_shares view made Postgres compute grade shares for every
-- assignment of every user (window functions block pushing the user filter down), then
-- discard all but the caller's. private.user_grade_shares() computes the same numbers
-- for one user's courses only; test 140 keeps it in agreement with the view.

create or replace function private.user_grade_shares(p_user_id uuid)
returns table (assignment_id uuid, course_id uuid, grade_share numeric)
language sql
stable
security invoker
set search_path = ''
as $$
with mine as (select c.id from public.courses c where c.user_id = p_user_id),
cat as (
  select gc.id, gc.course_id, greatest(gc.weight, 0) as weight,
         sum(greatest(gc.weight, 0)) over (partition by gc.course_id) as total_weight
  from public.grade_categories gc
  where gc.course_id in (select id from mine)
),
course_has_categories as (
  select c.id as course_id, exists (select 1 from public.grade_categories g where g.course_id = c.id) as has_categories
  from public.courses c
  where c.id in (select id from mine)
),
avg_points as (
  -- average points of items with points, per category (null category = whole course)
  select a.course_id, a.category_id, avg(a.points_possible) filter (where a.points_possible > 0) as avg_possible
  from public.assignments a
  where a.course_id in (select id from mine)
  group by a.course_id, a.category_id
),
course_avg as (
  select a.course_id, avg(a.points_possible) filter (where a.points_possible > 0) as avg_possible
  from public.assignments a
  where a.course_id in (select id from mine)
  group by a.course_id
),
pts as (
  select
    a.id, a.course_id, a.category_id, chc.has_categories,
    case
      when a.points_possible > 0 then a.points_possible
      when chc.has_categories then coalesce(ap.avg_possible, 1)
      else coalesce(ca.avg_possible, 1)
    end as points
  from public.assignments a
  join course_has_categories chc on chc.course_id = a.course_id
  left join avg_points ap on ap.course_id = a.course_id and ap.category_id is not distinct from a.category_id
  left join course_avg ca on ca.course_id = a.course_id
)
select
  p.id as assignment_id,
  p.course_id,
  case
    when not p.has_categories then
      p.points / nullif(sum(p.points) over (partition by p.course_id), 0) * 100
    when cat.id is null or cat.weight <= 0 or cat.total_weight <= 0 then 0
    else (cat.weight / cat.total_weight) * p.points / nullif(sum(p.points) over (partition by p.course_id, p.category_id), 0) * 100
  end as grade_share
from pts p
left join cat on cat.id = p.category_id
$$;

revoke execute on function private.user_grade_shares(uuid) from public, anon;
grant execute on function private.user_grade_shares(uuid) to authenticated, service_role;

create or replace function public.get_today_feed(p_date date default null)
returns table (
  item_type text,
  item_id uuid,
  assignment_id uuid,
  course_id uuid,
  course_name text,
  title text,
  kind public.assignment_kind,
  status public.assignment_status,
  block_kind public.study_block_kind,
  block_status public.study_block_status,
  starts_at timestamptz,
  ends_at timestamptz,
  due_at timestamptz,
  grade_share numeric,
  minutes_remaining integer,
  planned_minutes integer,
  priority numeric,
  overdue boolean,
  rank integer,
  -- Capacity for the day (same on every row) so one call renders the header too.
  capacity_minutes integer,
  studied_minutes integer
)
language plpgsql
stable
security invoker
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_tz text;
  v_date date;
  v_day_start timestamptz;
  v_day_end timestamptz;
  v_now timestamptz := now();
  v_capacity integer;
  v_daily integer;
  v_studied integer;
  v_left integer;
  r record;
  v_rank integer := 0;
  v_planned integer;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;

  select p.timezone, p.daily_study_minutes into v_tz, v_daily from public.profiles p where p.id = v_user_id;
  v_date := coalesce(p_date, (v_now at time zone v_tz)::date);
  v_day_start := v_date::timestamp at time zone v_tz;
  v_day_end := (v_date + 1)::timestamp at time zone v_tz;
  v_capacity := coalesce(public.study_capacity(v_user_id, v_date), 120);

  -- Time already studied today counts against the day's capacity.
  select coalesce(sum(extract(epoch from (least(coalesce(s.ended_at, v_now), v_day_end) - greatest(s.started_at, v_day_start))) / 60), 0)::integer
  into v_studied
  from public.study_sessions s
  where s.user_id = v_user_id
    and s.started_at < v_day_end
    and coalesce(s.ended_at, v_now) > v_day_start;

  v_left := greatest(v_capacity - v_studied, 0);

  -- 1. Review items first: the day's review, exam-prep, and practice-quiz blocks (done
  --    ones stay listed so they can be unchecked; missed ones drop off).
  for r in
    select b.id, b.assignment_id, b.course_id, c.name as course_name, b.kind, b.status,
           b.starts_at, b.ends_at, b.duration_minutes, a.title as assignment_title, a.due_at
    from public.study_blocks b
    join public.courses c on c.id = b.course_id and c.archived_at is null
    left join public.assignments a on a.id = b.assignment_id
    where b.user_id = v_user_id
      and b.kind in ('review', 'exam_prep', 'practice_quiz')
      and b.status in ('planned', 'done')
      and b.starts_at >= v_day_start and b.starts_at < v_day_end
    order by b.starts_at, b.id
  loop
    v_rank := v_rank + 1;
    if r.status = 'planned' then
      v_left := greatest(v_left - r.duration_minutes, 0);
    end if;
    item_type := 'review';
    item_id := r.id;
    assignment_id := r.assignment_id;
    course_id := r.course_id;
    course_name := r.course_name;
    title := case r.kind
      when 'practice_quiz' then 'Closed-note practice quiz'
      when 'exam_prep' then coalesce('Exam prep: ' || r.assignment_title, 'Exam prep')
      else coalesce('Review: ' || r.assignment_title, 'Review')
    end;
    kind := null;
    status := null;
    block_kind := r.kind;
    block_status := r.status;
    starts_at := r.starts_at;
    ends_at := r.ends_at;
    due_at := r.due_at;
    grade_share := null;
    minutes_remaining := case when r.status = 'planned' then r.duration_minutes else 0 end;
    planned_minutes := r.duration_minutes;
    priority := null;
    overdue := false;
    rank := v_rank;
    capacity_minutes := v_capacity;
    studied_minutes := v_studied;
    return next;
  end loop;

  -- 2. Then ranked tasks in the time that's left.
  for r in
    with logged as (
      select s.assignment_id, sum(coalesce(s.duration_minutes, 0)) as minutes
      from public.study_sessions s
      where s.user_id = v_user_id and s.assignment_id is not null
      group by s.assignment_id
    ),
    candidates as (
      select
        a.id, a.course_id, c.name as course_name, a.title, a.kind, a.status, a.due_at,
        coalesce(gs.grade_share, 0) as grade_share,
        greatest(coalesce(a.estimated_minutes, public.default_task_minutes(a.kind)) - coalesce(l.minutes, 0), 0)::integer as minutes_remaining
      from public.assignments a
      join public.courses c on c.id = a.course_id
      left join private.user_grade_shares(v_user_id) gs on gs.assignment_id = a.id
      left join logged l on l.assignment_id = a.id
      where c.user_id = v_user_id
        and c.archived_at is null
        and a.status in ('todo', 'in_progress')
        and (a.due_at is null or a.due_at between v_day_start - interval '7 days' and v_day_end + interval '30 days')
    )
    select
      cand.*,
      public.task_priority(cand.grade_share, cand.due_at, v_now, cand.minutes_remaining, cand.status, coalesce(v_daily, 120)) as score
    from candidates cand
    where cand.minutes_remaining > 0
    order by score desc, cand.due_at nulls last, cand.title
  loop
    exit when v_left <= 0;
    -- Today's fair share of the task: everything if it's due by the end of today,
    -- otherwise the remaining minutes spread over the days left (at least 25 minutes
    -- so work sessions stay meaningful).
    if r.due_at is null then
      v_planned := least(r.minutes_remaining, 30);
    elsif r.due_at <= v_day_end then
      v_planned := r.minutes_remaining;
    else
      v_planned := least(
        r.minutes_remaining,
        greatest(25, ceil(r.minutes_remaining / greatest(1, ceil(extract(epoch from (r.due_at - v_day_start)) / 86400)))::integer)
      );
    end if;
    v_planned := least(v_planned, v_left);
    continue when v_planned < 15 and v_planned < r.minutes_remaining; -- too small a slot to be useful
    v_left := v_left - v_planned;
    v_rank := v_rank + 1;

    item_type := 'task';
    item_id := r.id;
    assignment_id := r.id;
    course_id := r.course_id;
    course_name := r.course_name;
    title := r.title;
    kind := r.kind;
    status := r.status;
    block_kind := null;
    block_status := null;
    starts_at := null;
    ends_at := null;
    due_at := r.due_at;
    grade_share := round(r.grade_share, 2);
    minutes_remaining := r.minutes_remaining;
    planned_minutes := v_planned;
    priority := r.score;
    overdue := r.due_at is not null and r.due_at < v_now;
    rank := v_rank;
    capacity_minutes := v_capacity;
    studied_minutes := v_studied;
    return next;
  end loop;
end;
$$;

-- ==== 20260924006000_cross_user_link_fixes.sql
-- Fixes from the cross-user access suite (supabase/tests/e2e).
--
-- 1. A flashcard could point at another user's assignment: RLS only checked the card's
--    course, and the assignment foreign key didn't include the course. Cards (and card
--    generations, for defense in depth) now reference the assignment together with its
--    course, the way assignment_resources does, so the assignment must belong to the
--    card's course. Deleting the assignment still just unlinks the card.
update public.flashcards f
set assignment_id = null
where f.assignment_id is not null
  and not exists (
    select 1 from public.assignments a where a.id = f.assignment_id and a.course_id = f.course_id
  );
alter table public.flashcards drop constraint flashcards_assignment_id_fkey;
alter table public.flashcards
  add constraint flashcards_assignment_fkey foreign key (assignment_id, course_id)
  references public.assignments (id, course_id) on delete set null (assignment_id);

update public.card_generations g
set assignment_id = null
where g.assignment_id is not null
  and not exists (
    select 1 from public.assignments a where a.id = g.assignment_id and a.course_id = g.course_id
  );
alter table public.card_generations drop constraint card_generations_assignment_id_fkey;
alter table public.card_generations
  add constraint card_generations_assignment_fkey foreign key (assignment_id, course_id)
  references public.assignments (id, course_id) on delete set null (assignment_id);

-- 2. Registering a push token another account already had moved that account's row to the
--    caller and returned its id (and kept its device id and web push keys). A push token
--    identifies a device, so the device still moves to whoever signed in on it last (the
--    earlier account must stop getting notifications there), but now as a new row: the
--    earlier account's row is deleted and nothing of it is returned or carried over.
create or replace function public.register_push_token(
  p_provider public.push_provider,
  p_token text,
  p_platform text,
  p_device_id text default null,
  p_app_version text default null,
  p_web_push_keys jsonb default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user_id uuid := (select auth.uid());
  v_id uuid;
begin
  if v_user_id is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_provider = 'expo' and p_token !~ '^(Exponent|Expo)PushToken\[[A-Za-z0-9_-]+\]$' then
    raise exception 'not an Expo push token' using errcode = '22023';
  end if;

  delete from public.notification_tokens
  where provider = p_provider and token = p_token and user_id <> v_user_id;

  insert into public.notification_tokens (user_id, provider, token, platform, device_id, app_version, web_push_keys, last_seen_at, invalidated_at)
  values (v_user_id, p_provider, p_token, p_platform, p_device_id, p_app_version, p_web_push_keys, now(), null)
  on conflict (provider, token) do update
    set platform = excluded.platform,
        device_id = coalesce(excluded.device_id, public.notification_tokens.device_id),
        app_version = coalesce(excluded.app_version, public.notification_tokens.app_version),
        web_push_keys = coalesce(excluded.web_push_keys, public.notification_tokens.web_push_keys),
        last_seen_at = now(),
        invalidated_at = null
    where public.notification_tokens.user_id = v_user_id
  returning id into v_id;

  if v_id is null then
    -- Another account registered the same token between the delete and the insert.
    raise exception 'push token is being registered by another session' using errcode = '40001';
  end if;

  -- Token refresh: older tokens from the same device are no longer valid.
  if p_device_id is not null then
    update public.notification_tokens
    set invalidated_at = now()
    where user_id = v_user_id and device_id = p_device_id and provider = p_provider
      and id <> v_id and invalidated_at is null;
  end if;

  return v_id;
end;
$$;

-- ==== 20260924006100_provider_circuits.sql
-- Launch safety S9: when an outside provider (AI, Stripe, Expo, Resend, Google, ...) keeps
-- failing, every edge function stops calling it for 5 minutes. Each worker keeps its own
-- breaker (packages/core/src/resilience); this table shares "open until" between workers
-- and cron runs, so a new invocation doesn't start hammering a provider that's down.

create table private.provider_circuits (
  provider text primary key check (provider ~ '^[a-z]{2,20}$'),
  open_until timestamptz not null,
  opened_count integer not null default 1,
  updated_at timestamptz not null default now()
);

-- Providers that are off limits right now (service role only).
create or replace function public.provider_circuits_open()
returns table (provider text, open_until timestamptz)
language sql
stable
security definer
set search_path = ''
as $$
  select c.provider, c.open_until from private.provider_circuits c where c.open_until > now();
$$;

-- Record that a worker opened a provider's breaker; never shortens an existing pause, and
-- never pauses longer than 15 minutes whatever the caller asks.
create or replace function public.open_provider_circuit(p_provider text, p_until timestamptz)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into private.provider_circuits as c (provider, open_until)
  values (p_provider, least(p_until, now() + interval '15 minutes'))
  on conflict (provider) do update
    set open_until = greatest(c.open_until, excluded.open_until),
        opened_count = c.opened_count + 1,
        updated_at = now();
$$;

revoke all on private.provider_circuits from public, anon, authenticated;
revoke execute on function public.provider_circuits_open() from public, anon, authenticated;
revoke execute on function public.open_provider_circuit(text, timestamptz) from public, anon, authenticated;
grant execute on function public.provider_circuits_open() to service_role;
grant execute on function public.open_provider_circuit(text, timestamptz) to service_role;

-- ==== 20260924006200_rate_limits.sql
-- Launch safety S10: per-user and per-IP rate limits for every edge function (and per
-- token for the ICS feed). Fixed-window counters: one row per bucket per window. Buckets
-- name the function and a user id, or a SHA-256 of the client IP (raw IPs are never
-- stored); rows are deleted after a day.

create table private.rate_limit_counters (
  bucket text not null check (char_length(bucket) <= 200),
  window_start timestamptz not null,
  hits integer not null default 0,
  primary key (bucket, window_start)
);
create index rate_limit_counters_window_idx on private.rate_limit_counters (window_start);
revoke all on private.rate_limit_counters from public, anon, authenticated;

-- Counts one hit on `p_bucket` and says whether it's within `p_limit` per window.
-- Returns {allowed, remaining, retry_after} (retry_after in whole seconds, 0 if allowed).
create or replace function public.rate_limit_hit(p_bucket text, p_limit integer, p_window_seconds integer)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_start timestamptz;
  v_hits integer;
begin
  if p_limit < 1 or p_window_seconds not between 1 and 86400 or char_length(p_bucket) not between 1 and 200 then
    raise exception 'invalid rate limit' using errcode = '22023';
  end if;
  v_start := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);
  insert into private.rate_limit_counters as c (bucket, window_start, hits)
  values (p_bucket, v_start, 1)
  on conflict (bucket, window_start) do update set hits = c.hits + 1
  returning hits into v_hits;
  return jsonb_build_object(
    'allowed', v_hits <= p_limit,
    'remaining', greatest(p_limit - v_hits, 0),
    'retry_after', case when v_hits <= p_limit then 0
      else greatest(1, ceil(extract(epoch from (v_start + make_interval(secs => p_window_seconds) - now()))))::integer end
  );
end;
$$;

revoke execute on function public.rate_limit_hit(text, integer, integer) from public, anon, authenticated;
grant execute on function public.rate_limit_hit(text, integer, integer) to service_role;

create or replace function private.cleanup_rate_limits()
returns integer
language sql
security definer
set search_path = ''
as $$
  with gone as (
    delete from private.rate_limit_counters where window_start < now() - interval '1 day' returning 1
  )
  select count(*)::integer from gone;
$$;
revoke execute on function private.cleanup_rate_limits() from public, anon, authenticated;

select cron.schedule('cleanup-rate-limits', '*/15 * * * *', $$ select private.cleanup_rate_limits() $$);

-- ==== 20260924006300_age_gate.sql
-- Launch safety S12: StudyPulse is for people 13 and older (COPPA; the audience includes
-- high schoolers). Nobody under 13 gets an account, and we keep no birth date: the
-- sign-up form sends a birth month ("YYYY-MM"), which is checked and discarded as the
-- account is created. Only the time the age was confirmed is kept.
--
-- - Email sign-ups must include birth_month. The before_user_created hook refuses a
--   missing or under-13 one with a clear message; a trigger on auth.users refuses the
--   under-13 ones again, in case the hook is off.
-- - Apple and Google sign-ups can't carry a birth month, so those accounts start
--   unconfirmed. The app asks right after sign-in (confirm_age). Under 13: the account is
--   deleted on the spot.
-- - Until the age is confirmed, an account can't finish onboarding, create a course, or
--   upload a syllabus.
--
-- Age is computed as if the birthday were the last day of the birth month, so rounding
-- never lets someone in early.

alter table public.profiles add column age_confirmed_at timestamptz;
-- Accounts created before the gate existed.
update public.profiles set age_confirmed_at = created_at where age_confirmed_at is null;

create or replace function private.age_in_years(p_birth_month text, p_on date default current_date)
returns integer
language plpgsql
stable
set search_path = ''
as $$
declare
  v_birth date;
begin
  if p_birth_month is null or p_birth_month !~ '^(19|20)\d{2}-(0[1-9]|1[0-2])$' then
    return null;
  end if;
  v_birth := (to_date(p_birth_month || '-01', 'YYYY-MM-DD') + interval '1 month' - interval '1 day')::date;
  if v_birth > p_on then
    return null;
  end if;
  return extract(year from age(p_on, v_birth))::integer;
end;
$$;

-- Backstop on every new account: refuse under-13 birth months, and never store one.
create or replace function private.check_age_on_signup()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_birth_month text := new.raw_user_meta_data ->> 'birth_month';
  v_age integer;
begin
  if v_birth_month is null then
    return new;
  end if;
  v_age := private.age_in_years(v_birth_month);
  if v_age is null then
    raise exception 'Enter a valid birth month.' using errcode = '22023';
  end if;
  if v_age < 13 then
    raise exception 'StudyPulse is for people 13 and older.' using errcode = 'SPA13';
  end if;
  new.raw_user_meta_data := new.raw_user_meta_data - 'birth_month';
  new.raw_app_meta_data := coalesce(new.raw_app_meta_data, '{}'::jsonb)
    || jsonb_build_object('age_confirmed_at', now());
  return new;
end;
$$;
revoke execute on function private.check_age_on_signup() from public, anon, authenticated;

create trigger check_age_on_signup
before insert on auth.users
for each row execute function private.check_age_on_signup();

-- The profile records when the age was confirmed at sign-up (from app metadata, which
-- users can't edit).
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  tz text := new.raw_user_meta_data ->> 'timezone';
begin
  insert into public.profiles (id, display_name, timezone, school, age_confirmed_at)
  values (
    new.id,
    left(nullif(trim(new.raw_user_meta_data ->> 'display_name'), ''), 100),
    case when public.is_valid_timezone(tz) then tz else 'UTC' end,
    left(nullif(trim(new.raw_user_meta_data ->> 'school'), ''), 200),
    (new.raw_app_meta_data ->> 'age_confirmed_at')::timestamptz
  );
  return new;
end;
$$;

-- Auth hook (before_user_created): a clean refusal before anything is written.
create or replace function public.hook_before_user_created(event jsonb)
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_provider text := event -> 'user' -> 'app_metadata' ->> 'provider';
  v_birth_month text := event -> 'user' -> 'user_metadata' ->> 'birth_month';
  v_age integer := private.age_in_years(v_birth_month);
begin
  if v_birth_month is null then
    -- Apple/Google: asked right after sign-in instead.
    if v_provider is not null and v_provider not in ('email', 'phone') then
      return '{}'::jsonb;
    end if;
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 400, 'message', 'Enter your birth month and year to create an account.'));
  end if;
  if v_age is null then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 400, 'message', 'Enter a valid birth month and year.'));
  end if;
  if v_age < 13 then
    return jsonb_build_object('error', jsonb_build_object(
      'http_code', 403, 'message', 'Sorry, StudyPulse is for people 13 and older.'));
  end if;
  return '{}'::jsonb;
end;
$$;
revoke execute on function public.hook_before_user_created(jsonb) from public, anon, authenticated;
grant execute on function public.hook_before_user_created(jsonb) to supabase_auth_admin;
grant execute on function private.age_in_years(text, date) to supabase_auth_admin;

-- For accounts that started unconfirmed (Apple/Google). Under 13: the account and
-- everything in it is deleted at once, and 'blocked' is returned.
create or replace function public.confirm_age(p_birth_month text)
returns text
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_age integer := private.age_in_years(p_birth_month);
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if (select age_confirmed_at from public.profiles where id = v_user) is not null then
    return 'confirmed';
  end if;
  if v_age is null then
    raise exception 'Enter a valid birth month and year.' using errcode = '22023';
  end if;
  if v_age < 13 then
    delete from auth.users where id = v_user;
    return 'blocked';
  end if;
  update public.profiles set age_confirmed_at = now() where id = v_user;
  return 'confirmed';
end;
$$;
revoke execute on function public.confirm_age(text) from public, anon;
grant execute on function public.confirm_age(text) to authenticated;

-- Nothing gets created for an account whose age isn't confirmed.
create or replace function private.require_age_confirmed()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if (select p.age_confirmed_at from public.profiles p where p.id = new.user_id) is null then
    raise exception 'Confirm your age to continue.' using errcode = 'SPA14', hint = 'age_unconfirmed';
  end if;
  return new;
end;
$$;
revoke execute on function private.require_age_confirmed() from public, anon, authenticated;

create trigger courses_require_age_confirmed
before insert on public.courses
for each row execute function private.require_age_confirmed();
create trigger syllabus_uploads_require_age_confirmed
before insert on public.syllabus_uploads
for each row execute function private.require_age_confirmed();

create or replace function public.complete_onboarding(
  p_display_name text,
  p_timezone text,
  p_daily_study_minutes int,
  p_study_start_time time
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if (select age_confirmed_at from public.profiles where id = v_user) is null then
    raise exception 'Confirm your age to continue.' using errcode = 'SPA14', hint = 'age_unconfirmed';
  end if;
  if not public.is_valid_timezone(p_timezone) then
    raise exception 'unknown timezone %', p_timezone using errcode = '22023';
  end if;
  update public.profiles
  set display_name = nullif(btrim(p_display_name), ''),
      timezone = p_timezone,
      daily_study_minutes = p_daily_study_minutes,
      study_start_time = p_study_start_time,
      onboarded_at = coalesce(onboarded_at, now())
  where id = v_user;
end;
$$;

-- ==== 20260924006400_marketing_email.sql
-- Launch safety S15: marketing email is separate from the email students ask for.
--
-- Transactional (sent because of something the student did or asked for): the daily
-- digest, subscription confirmations, renewal reminders, account and security email.
-- Marketing (product news, tips, offers): only to students who opted in (off by default),
-- always with our postal address and a one-click unsubscribe that takes effect at once.
-- The two are unsubscribed separately (tokens are scoped), so leaving marketing never
-- turns off reminders and vice versa. See packages/core/src/notify/email-policy.ts.

alter table public.notification_prefs
  add column marketing_emails boolean not null default false,
  -- When the student last opted in (the consent record); cleared on opt-out.
  add column marketing_opt_in_at timestamptz;

grant update (marketing_emails) on public.notification_prefs to authenticated;

create or replace function private.stamp_marketing_consent()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if new.marketing_emails and not coalesce(old.marketing_emails, false) then
    new.marketing_opt_in_at := now();
  elsif not new.marketing_emails then
    new.marketing_opt_in_at := null;
  end if;
  return new;
end;
$$;
revoke execute on function private.stamp_marketing_consent() from public, anon, authenticated;

create trigger notification_prefs_marketing_consent
before insert or update of marketing_emails on public.notification_prefs
for each row execute function private.stamp_marketing_consent();

-- One-click unsubscribe from marketing (service role, from a signed link). Immediate.
create or replace function public.unsubscribe_marketing(p_user_id uuid)
returns boolean
language sql
security definer
set search_path = ''
as $$
  with updated as (
    update public.notification_prefs set marketing_emails = false
    where user_id = p_user_id and marketing_emails
    returning 1
  )
  select exists (select 1 from public.notification_prefs where user_id = p_user_id);
$$;
revoke execute on function public.unsubscribe_marketing(uuid) from public, anon, authenticated;
grant execute on function public.unsubscribe_marketing(uuid) to service_role;

create or replace function public.get_settings()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'profile', jsonb_build_object(
        'display_name', p.display_name,
        'school', p.school,
        'timezone', p.timezone,
        'daily_study_minutes', p.daily_study_minutes,
        'study_start_time', to_char(p.study_start_time, 'HH24:MI'),
        'card_tasks_enabled', p.card_tasks_enabled,
        'plan_tier', p.plan_tier,
        'onboarded_at', p.onboarded_at
      ),
      'notifications', (
        select jsonb_build_object(
          'push_enabled', n.push_enabled,
          'email_digest_enabled', n.email_digest_enabled,
          'marketing_emails', n.marketing_emails,
          'remind_24h', n.remind_24h,
          'remind_2h', n.remind_2h,
          'exam_countdown', n.exam_countdown,
          'morning_digest', n.morning_digest,
          'morning_digest_time', to_char(n.morning_digest_time, 'HH24:MI'),
          'quiet_hours_enabled', n.quiet_hours_enabled,
          'quiet_hours_start', to_char(n.quiet_hours_start, 'HH24:MI'),
          'quiet_hours_end', to_char(n.quiet_hours_end, 'HH24:MI'),
          'daily_cap', n.daily_cap
        )
        from public.notification_prefs n where n.user_id = v_user
      ),
      -- Devices that can receive reminders, so the screen can say where they go.
      'devices', jsonb_build_object(
        'mobile', (select count(*) from public.notification_tokens t
                   where t.user_id = v_user and t.provider = 'expo' and t.invalidated_at is null),
        'web', (select count(*) from public.notification_tokens t
                where t.user_id = v_user and t.provider = 'web_push' and t.invalidated_at is null)
      )
    )
    from public.profiles p
    where p.id = v_user
  );
end;
$$;

-- ==== 20260924006500_content_takedowns.sql
-- Launch safety S17: a record of every copyright notice and what was removed, and one
-- service-only function that removes reported content. Operators run
-- scripts/takedown.mjs (it also deletes the file from storage); see docs/takedowns.md.

create table private.content_takedowns (
  id uuid primary key default gen_random_uuid(),
  received_at timestamptz not null,
  -- Our reference for the notice (ticket or email id), not the notice itself.
  notice_ref text not null check (char_length(notice_ref) between 1 and 200),
  target_type text not null check (target_type in ('syllabus_upload', 'flashcard', 'assignment_resource')),
  target_id uuid not null,
  -- Whose content it was (kept after the content is gone, for repeat-infringer checks).
  user_id uuid,
  reason text check (char_length(reason) <= 2000),
  removed_at timestamptz not null default now(),
  restored_at timestamptz
);
create index content_takedowns_user_idx on private.content_takedowns (user_id);
revoke all on private.content_takedowns from public, anon, authenticated;

-- Removes one reported item and records it. Returns the owner's user id (null if the
-- item was already gone). Service role only.
create or replace function public.takedown_content(
  p_target_type text,
  p_target_id uuid,
  p_notice_ref text,
  p_received_at timestamptz,
  p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid;
begin
  if p_target_type = 'syllabus_upload' then
    -- Keep the row (the course may already exist) but drop the text and mark it removed;
    -- the script deletes the stored file.
    update public.syllabus_uploads
    set extracted_text = null,
        status = 'failed',
        error = 'Removed after a copyright notice.'
    where id = p_target_id
    returning user_id into v_user;
  elsif p_target_type = 'flashcard' then
    delete from public.flashcards f using public.courses c
    where f.id = p_target_id and c.id = f.course_id
    returning c.user_id into v_user;
  elsif p_target_type = 'assignment_resource' then
    delete from public.assignment_resources r using public.courses c
    where r.id = p_target_id and c.id = r.course_id
    returning c.user_id into v_user;
  else
    raise exception 'unknown target type %', p_target_type using errcode = '22023';
  end if;

  insert into private.content_takedowns (received_at, notice_ref, target_type, target_id, user_id, reason)
  values (p_received_at, p_notice_ref, p_target_type, p_target_id, v_user, p_reason);
  return v_user;
end;
$$;

-- How many takedowns an account has had (for the repeat-infringer policy).
create or replace function public.takedown_count(p_user_id uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer from private.content_takedowns
  where user_id = p_user_id and restored_at is null;
$$;

revoke execute on function public.takedown_content(text, uuid, text, timestamptz, text) from public, anon, authenticated;
revoke execute on function public.takedown_count(uuid) from public, anon, authenticated;
grant execute on function public.takedown_content(text, uuid, text, timestamptz, text) to service_role;
grant execute on function public.takedown_count(uuid) to service_role;

-- ==== 20260924006600_terms_acceptances.sql
-- Launch safety S21: which Terms of Service version each user accepted, and when, at
-- sign-up and at checkout. Evidence for disputes (S20) and for enforcing the terms.
--
-- - Email sign-up: the form sends terms_version with the sign-up; a trigger records it
--   as the account is created.
-- - Apple/Google sign-up: recorded when the student continues past the age question
--   (accept_terms).
-- - Checkout: stripe-checkout records it (service role) and puts terms_version on the
--   Stripe session and subscription.

create or replace function private.current_terms_version()
returns text
language sql
immutable
set search_path = ''
as $$ select '2026-09-25'::text $$;

create table public.terms_acceptances (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  version text not null check (version ~ '^\d{4}-\d{2}-\d{2}$'),
  context text not null check (context in ('signup', 'checkout', 'reaccept')),
  accepted_at timestamptz not null default now()
);
create index terms_acceptances_user_idx on public.terms_acceptances (user_id, accepted_at desc);

alter table public.terms_acceptances enable row level security;
revoke all on public.terms_acceptances from anon, authenticated;
grant select on public.terms_acceptances to authenticated;
create policy "Users can view their own terms acceptances" on public.terms_acceptances
for select to authenticated using ((select auth.uid()) = user_id);

-- Email sign-ups carry terms_version in their metadata; record it once the profile exists
-- (this trigger's name sorts after on_auth_user_created, so it runs after it).
create or replace function private.record_signup_terms()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_version text := new.raw_user_meta_data ->> 'terms_version';
begin
  if v_version is not null and v_version = private.current_terms_version() then
    insert into public.terms_acceptances (user_id, version, context) values (new.id, v_version, 'signup');
  end if;
  return new;
end;
$$;
revoke execute on function private.record_signup_terms() from public, anon, authenticated;

create trigger on_auth_user_created_terms
after insert on auth.users
for each row execute function private.record_signup_terms();

-- The signed-in user accepts the current terms (Apple/Google sign-up, or a new version).
create or replace function public.accept_terms(p_version text)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_version is distinct from private.current_terms_version() then
    raise exception 'These aren''t the current terms. Reload and try again.' using errcode = '22023';
  end if;
  insert into public.terms_acceptances (user_id, version, context)
  values (
    v_user,
    p_version,
    case when exists (select 1 from public.terms_acceptances where user_id = v_user) then 'reaccept' else 'signup' end
  );
end;
$$;
revoke execute on function public.accept_terms(text) from public, anon;
grant execute on function public.accept_terms(text) to authenticated;

-- Checkout (service role): the user saw and accepted the current terms on the pricing page.
create or replace function public.record_checkout_terms(p_user_id uuid)
returns text
language sql
security definer
set search_path = ''
as $$
  insert into public.terms_acceptances (user_id, version, context)
  values (p_user_id, private.current_terms_version(), 'checkout')
  returning version;
$$;
revoke execute on function public.record_checkout_terms(uuid) from public, anon, authenticated;
grant execute on function public.record_checkout_terms(uuid) to service_role;

-- Whether the user has accepted the current terms (clients prompt when it's false).
create or replace function public.terms_current()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.terms_acceptances
    where user_id = (select auth.uid()) and version = private.current_terms_version()
  );
$$;
revoke execute on function public.terms_current() from public, anon;
grant execute on function public.terms_current() to authenticated;

-- ==== 20260924006700_billing_disputes.sql
-- Launch safety S20: chargebacks. stripe-webhook records each dispute here, gathers
-- evidence (dispute_evidence_facts), stages it on the Stripe dispute, and alerts the
-- owner, louder when disputes pass 0.5% of charges in the last 90 days.

create table private.billing_disputes (
  dispute_id text primary key check (dispute_id ~ '^dp_[A-Za-z0-9]+$'),
  charge_id text not null,
  user_id uuid references public.profiles (id) on delete set null,
  amount_cents integer not null,
  currency text not null,
  reason text not null,
  evidence_due_by timestamptz,
  -- The text evidence staged on the dispute, as sent.
  evidence jsonb,
  created_at timestamptz not null default now()
);
create index billing_disputes_created_idx on private.billing_disputes (created_at);
create index billing_disputes_user_idx on private.billing_disputes (user_id);
revoke all on private.billing_disputes from public, anon, authenticated;

-- What we know about an account, for dispute evidence (service role only). Sign-ins are
-- the account's sessions (time and browser; no IP addresses).
create or replace function public.dispute_evidence_facts(p_user_id uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object(
    'email', (select u.email from auth.users u where u.id = p_user_id),
    'name', (select p.display_name from public.profiles p where p.id = p_user_id),
    'termsAcceptances', coalesce((
      select jsonb_agg(jsonb_build_object('version', t.version, 'context', t.context,
                                          'accepted_at', t.accepted_at) order by t.accepted_at)
      from public.terms_acceptances t where t.user_id = p_user_id
    ), '[]'::jsonb),
    'signIns', coalesce((
      select jsonb_agg(jsonb_build_object('at', s.created_at, 'user_agent', left(s.user_agent, 200))
                       order by s.created_at desc)
      from (select * from auth.sessions where user_id = p_user_id order by created_at desc limit 20) s
    ), '[]'::jsonb),
    'usage', jsonb_build_object(
      'courses', (select count(*) from public.courses c where c.user_id = p_user_id),
      'uploads', (select count(*) from public.syllabus_uploads x where x.user_id = p_user_id),
      'study_sessions', (select count(*) from public.study_sessions s where s.user_id = p_user_id),
      'study_minutes', (select coalesce(sum(s.duration_minutes), 0) from public.study_sessions s
                        where s.user_id = p_user_id),
      'first_active_at', (select min(s.started_at) from public.study_sessions s where s.user_id = p_user_id),
      'last_active_at', (select max(s.started_at) from public.study_sessions s where s.user_id = p_user_id)
    )
  );
$$;

-- Records a dispute (idempotent on its id) and returns {new, disputes, charges}: whether
-- it was new (so a Stripe retry doesn't alert twice) and the 90-day counts, where charges
-- are paid Stripe invoices seen by the webhook.
create or replace function public.record_dispute(
  p_dispute_id text,
  p_charge_id text,
  p_amount_cents integer,
  p_currency text,
  p_reason text,
  p_user_id uuid default null,
  p_evidence_due_by timestamptz default null,
  p_evidence jsonb default null
)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_new boolean;
begin
  insert into private.billing_disputes
    (dispute_id, charge_id, user_id, amount_cents, currency, reason, evidence_due_by, evidence)
  values
    (p_dispute_id, p_charge_id, p_user_id, p_amount_cents, p_currency, p_reason, p_evidence_due_by, p_evidence)
  on conflict (dispute_id) do nothing
  returning true into v_new;
  return jsonb_build_object(
    'new', coalesce(v_new, false),
    'disputes', (select count(*) from private.billing_disputes
                 where created_at > now() - interval '90 days'),
    'charges', (select count(*) from public.billing_events
                where provider = 'stripe' and event_type = 'invoice.paid'
                  and event_created_at > now() - interval '90 days')
  );
end;
$$;

revoke execute on function public.dispute_evidence_facts(uuid) from public, anon, authenticated;
revoke execute on function public.record_dispute(text, text, integer, text, text, uuid, timestamptz, jsonb) from public, anon, authenticated;
grant execute on function public.dispute_evidence_facts(uuid) to service_role;
grant execute on function public.record_dispute(text, text, integer, text, text, uuid, timestamptz, jsonb) to service_role;

-- ==== 20260924006800_privacy_choices.sql
-- Launch safety S23–S24: consent, recorded and honored.
--
-- consent_log: every consent decision with its time and the policy version it was given
-- under: marketing email (S15), product analytics and browser error reports (S23), and
-- the Terms (S21 keeps its own table, terms_acceptances). Rows are appended, never edited.
--
-- profiles.analytics_allowed: whether this student's product events may go to PostHog.
-- Off for students who rejected it (and, in the EU and UK, until they accept: the web
-- app sends the choice at sign-in). Events for students who haven't allowed it are never
-- stored, so they never leave the database.

create or replace function private.current_privacy_version()
returns text
language sql
immutable
set search_path = ''
as $$ select '2026-09-25'::text $$;

create table public.consent_log (
  id bigint generated always as identity primary key,
  user_id uuid not null references public.profiles (id) on delete cascade,
  kind text not null check (kind in ('marketing_email', 'analytics', 'error_reports')),
  granted boolean not null,
  policy_version text not null,
  -- Where the choice was made: banner, settings, signup, unsubscribe_link.
  source text not null check (char_length(source) between 1 and 40),
  recorded_at timestamptz not null default now()
);
create index consent_log_user_idx on public.consent_log (user_id, kind, recorded_at desc);
alter table public.consent_log enable row level security;
revoke all on public.consent_log from anon, authenticated;
grant select on public.consent_log to authenticated;
create policy "Users can view their own consent history" on public.consent_log
for select to authenticated using ((select auth.uid()) = user_id);

alter table public.profiles
  add column analytics_allowed boolean not null default true,
  add column error_reports_allowed boolean not null default true;

-- The signed-in student's choices for product analytics and error reports.
create or replace function public.set_privacy_choices(
  p_analytics boolean,
  p_error_reports boolean,
  p_source text default 'settings'
)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_old record;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_source not in ('banner', 'settings', 'signin') then
    raise exception 'unknown source' using errcode = '22023';
  end if;
  select analytics_allowed, error_reports_allowed into v_old from public.profiles where id = v_user;
  update public.profiles
  set analytics_allowed = p_analytics, error_reports_allowed = p_error_reports
  where id = v_user;
  if v_old.analytics_allowed is distinct from p_analytics or p_source = 'banner' then
    insert into public.consent_log (user_id, kind, granted, policy_version, source)
    values (v_user, 'analytics', p_analytics, private.current_privacy_version(), p_source);
  end if;
  if v_old.error_reports_allowed is distinct from p_error_reports or p_source = 'banner' then
    insert into public.consent_log (user_id, kind, granted, policy_version, source)
    values (v_user, 'error_reports', p_error_reports, private.current_privacy_version(), p_source);
  end if;
  -- Withdrawn: drop what hasn't been sent yet.
  if not p_analytics then
    delete from public.analytics_events where user_id = v_user and sent_at is null;
  end if;
end;
$$;
revoke execute on function public.set_privacy_choices(boolean, boolean, text) from public, anon;
grant execute on function public.set_privacy_choices(boolean, boolean, text) to authenticated;

-- Events for students who haven't allowed analytics are never stored.
create or replace function private.analytics_require_consent()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if coalesce((select p.analytics_allowed from public.profiles p where p.id = new.user_id), false) then
    return new;
  end if;
  return null;
end;
$$;
revoke execute on function private.analytics_require_consent() from public, anon, authenticated;
create trigger analytics_events_require_consent
before insert on public.analytics_events
for each row execute function private.analytics_require_consent();

-- Marketing email consent (S15) is logged too, with the policy version.
create or replace function private.log_marketing_consent()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' and not new.marketing_emails then
    return new;
  end if;
  if tg_op = 'UPDATE' and new.marketing_emails is not distinct from old.marketing_emails then
    return new;
  end if;
  insert into public.consent_log (user_id, kind, granted, policy_version, source)
  values (
    new.user_id, 'marketing_email', new.marketing_emails, private.current_privacy_version(),
    case when (select auth.uid()) is null then 'unsubscribe_link' else 'settings' end
  );
  return new;
end;
$$;
revoke execute on function private.log_marketing_consent() from public, anon, authenticated;
create trigger notification_prefs_log_marketing_consent
after insert or update of marketing_emails on public.notification_prefs
for each row execute function private.log_marketing_consent();

-- get_settings also returns the privacy choices.
create or replace function public.get_settings()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'profile', jsonb_build_object(
        'display_name', p.display_name,
        'school', p.school,
        'timezone', p.timezone,
        'daily_study_minutes', p.daily_study_minutes,
        'study_start_time', to_char(p.study_start_time, 'HH24:MI'),
        'card_tasks_enabled', p.card_tasks_enabled,
        'plan_tier', p.plan_tier,
        'onboarded_at', p.onboarded_at,
        'analytics_allowed', p.analytics_allowed,
        'error_reports_allowed', p.error_reports_allowed
      ),
      'notifications', (
        select jsonb_build_object(
          'push_enabled', n.push_enabled,
          'email_digest_enabled', n.email_digest_enabled,
          'marketing_emails', n.marketing_emails,
          'remind_24h', n.remind_24h,
          'remind_2h', n.remind_2h,
          'exam_countdown', n.exam_countdown,
          'morning_digest', n.morning_digest,
          'morning_digest_time', to_char(n.morning_digest_time, 'HH24:MI'),
          'quiet_hours_enabled', n.quiet_hours_enabled,
          'quiet_hours_start', to_char(n.quiet_hours_start, 'HH24:MI'),
          'quiet_hours_end', to_char(n.quiet_hours_end, 'HH24:MI'),
          'daily_cap', n.daily_cap
        )
        from public.notification_prefs n where n.user_id = v_user
      ),
      -- Devices that can receive reminders, so the screen can say where they go.
      'devices', jsonb_build_object(
        'mobile', (select count(*) from public.notification_tokens t
                   where t.user_id = v_user and t.provider = 'expo' and t.invalidated_at is null),
        'web', (select count(*) from public.notification_tokens t
                where t.user_id = v_user and t.provider = 'web_push' and t.invalidated_at is null)
      )
    )
    from public.profiles p
    where p.id = v_user
  );
end;
$$;

-- ==== 20260924006900_data_retention.sql
-- Launch safety S25: keep personal data only as long as it's needed. A daily job deletes:
-- - notification_log rows (they hold reminder text, i.e. assignment titles) after 90 days;
-- - study_plan_alerts after 90 days;
-- - Google/Canvas OAuth state rows a day after they expire;
-- - external calendar busy times 30 days after they end.
-- Other retention (analytics outbox, dedupe keys, push tokens, rate-limit counters) was
-- already scheduled; the full list is in docs/data-inventory.md.

create or replace function private.cleanup_retention()
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_log integer;
  v_alerts integer;
  v_states integer;
  v_busy integer;
begin
  delete from public.notification_log where created_at < now() - interval '90 days';
  get diagnostics v_log = row_count;
  delete from public.study_plan_alerts where created_at < now() - interval '90 days';
  get diagnostics v_alerts = row_count;
  delete from public.google_oauth_states where expires_at < now() - interval '1 day';
  get diagnostics v_states = row_count;
  delete from public.lms_oauth_states where expires_at < now() - interval '1 day';
  get diagnostics v_busy = row_count;
  v_states := v_states + v_busy;
  delete from public.external_busy_times where ends_at < now() - interval '30 days';
  get diagnostics v_busy = row_count;
  return jsonb_build_object('notification_log', v_log, 'study_plan_alerts', v_alerts,
                            'oauth_states', v_states, 'external_busy_times', v_busy);
end;
$$;
revoke execute on function private.cleanup_retention() from public, anon, authenticated;

select cron.schedule('cleanup-retention', '43 3 * * *', $$ select private.cleanup_retention() $$);

-- ==== 20260924007000_admin_role.sql
-- Launch safety S32: an admin role, stored where only the service role can write it.
--
-- An admin is a user whose auth.users.raw_app_meta_data has "role": "admin". App metadata
-- can only be changed with the service-role key (Supabase's admin API, or
-- scripts/set-admin.mjs); users can edit user_metadata but never app_metadata, and
-- user_metadata is never consulted here. The check reads the live row rather than the
-- JWT claim, so removing someone's admin role takes effect on their next request instead
-- of when their token expires. Every admin RPC and edge function checks it server-side
-- and answers 403 otherwise; every admin action is recorded.

create or replace function private.is_admin()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select coalesce(
    (select u.raw_app_meta_data ->> 'role' = 'admin' from auth.users u where u.id = auth.uid()),
    false
  );
$$;
revoke execute on function private.is_admin() from public, anon;
grant execute on function private.is_admin() to authenticated, service_role;

-- Raises insufficient_privilege (PostgREST answers 403) unless the caller is an admin.
create or replace function private.require_admin()
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  if not private.is_admin() then
    raise exception 'admins only' using errcode = '42501';
  end if;
  return auth.uid();
end;
$$;
revoke execute on function private.require_admin() from public, anon;
grant execute on function private.require_admin() to authenticated, service_role;

-- Every admin action: who, what, on what, and when. Service role and admins read it
-- through the RPCs below; nobody can edit it.
create table private.admin_actions (
  id bigint generated always as identity primary key,
  admin_id uuid not null,
  action text not null check (action ~ '^[a-z_]{3,40}$'),
  target_type text,
  target_id text check (char_length(target_id) <= 200),
  details jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index admin_actions_created_at_idx on private.admin_actions (created_at desc);
revoke all on private.admin_actions from public, anon, authenticated;
grant select, insert on private.admin_actions to service_role;

-- Records an admin action (used by the admin RPCs and the admin edge functions, which
-- call it with the service role after checking the caller).
create or replace function private.log_admin_action(
  p_admin_id uuid,
  p_action text,
  p_target_type text,
  p_target_id text,
  p_details jsonb default '{}'::jsonb
)
returns void
language sql
security definer
set search_path = ''
as $$
  insert into private.admin_actions (admin_id, action, target_type, target_id, details)
  values (p_admin_id, p_action, p_target_type, p_target_id, coalesce(p_details, '{}'::jsonb));
$$;
revoke execute on function private.log_admin_action(uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function private.log_admin_action(uuid, text, text, text, jsonb) to service_role;

-- Admin: remove reported content (S17). Same effect as the operator script's database
-- step; the script (or the storage API) still deletes an upload's stored file.
create or replace function public.admin_takedown_content(
  p_target_type text,
  p_target_id uuid,
  p_notice_ref text,
  p_received_at timestamptz,
  p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_admin uuid := private.require_admin();
  v_owner uuid;
begin
  if char_length(coalesce(p_notice_ref, '')) not between 1 and 200 then
    raise exception 'notice reference required' using errcode = '22023';
  end if;
  v_owner := public.takedown_content(p_target_type, p_target_id, p_notice_ref, p_received_at, p_reason);
  perform private.log_admin_action(
    v_admin, 'takedown', p_target_type, p_target_id::text,
    jsonb_build_object('notice_ref', p_notice_ref, 'owner_found', v_owner is not null)
  );
  return v_owner;
end;
$$;
revoke execute on function public.admin_takedown_content(text, uuid, text, timestamptz, text) from public, anon;
grant execute on function public.admin_takedown_content(text, uuid, text, timestamptz, text) to authenticated;

-- Admin: an account's takedown count (repeat-infringer policy).
create or replace function public.admin_takedown_count(p_user_id uuid)
returns integer
language plpgsql
stable
security definer
set search_path = ''
as $$
begin
  perform private.require_admin();
  return public.takedown_count(p_user_id);
end;
$$;
revoke execute on function public.admin_takedown_count(uuid) from public, anon;
grant execute on function public.admin_takedown_count(uuid) to authenticated;

-- The admin edge functions log through this (the private schema isn't exposed to the API).
create or replace function public.record_admin_action(
  p_admin_id uuid,
  p_action text,
  p_target_type text,
  p_target_id text,
  p_details jsonb default '{}'::jsonb
)
returns void
language sql
security definer
set search_path = ''
as $$
  select private.log_admin_action(p_admin_id, p_action, p_target_type, p_target_id, p_details);
$$;
revoke execute on function public.record_admin_action(uuid, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.record_admin_action(uuid, text, text, text, jsonb) to service_role;

-- ==== 20260924007100_rls_everywhere.sql
-- Launch safety S33: row level security on every table we own, not just public ones.
-- Tables in `private` were already out of reach (no grants to API roles, schema not
-- exposed), but RLS with no policies adds a second lock: if a grant or an exposed schema
-- is ever added by mistake, API roles still read nothing. The service role (BYPASSRLS)
-- and SECURITY DEFINER functions owned by postgres are unaffected.
do $$
declare
  t record;
begin
  for t in
    select n.nspname, c.relname
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where c.relkind in ('r', 'p')
      and n.nspname in ('private', 'request_guard')
      and not c.relrowsecurity
  loop
    execute format('alter table %I.%I enable row level security', t.nspname, t.relname);
  end loop;
end;
$$;

-- ==== 20260926000100_ai_consent.sql
-- Launch audit L2-AI: ask before sending anything to the AI provider.
--
-- App Store guideline 5.1.2(i) and Google Play's user data policy both require an in-app
-- disclosure that names the AI provider, says what is sent and why, and gets an explicit
-- "yes" before the first transmission. A line in the privacy policy is not enough.
--
-- profiles.ai_processing_allowed: off until the student says yes in the app (the consent
-- prompt before their first syllabus or card generation, or Settings). Existing accounts
-- start off too, so everyone sees the prompt once.
--
-- Enforced in the database, not only in the apps: a syllabus upload or card generation
-- can't be created for an account that hasn't allowed it (errcode SPA15), and withdrawing
-- consent in Settings stops anything new from being sent. Every decision is appended to
-- consent_log with the policy version, like the other consents (S23).

alter table public.consent_log drop constraint consent_log_kind_check;
alter table public.consent_log add constraint consent_log_kind_check
  check (kind in ('marketing_email', 'analytics', 'error_reports', 'ai_processing'));

alter table public.profiles
  add column ai_processing_allowed boolean not null default false;

-- The signed-in student's choice. p_source: 'prompt' (the in-context consent screen) or
-- 'settings'.
create or replace function public.set_ai_consent(p_allowed boolean, p_source text default 'settings')
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_old boolean;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if p_allowed is null then
    raise exception 'choose yes or no' using errcode = '22023';
  end if;
  if p_source not in ('prompt', 'settings') then
    raise exception 'unknown source' using errcode = '22023';
  end if;
  select ai_processing_allowed into v_old from public.profiles where id = v_user;
  update public.profiles set ai_processing_allowed = p_allowed where id = v_user;
  -- A prompt answer is always logged (it's the moment of consent); Settings only on change.
  if v_old is distinct from p_allowed or p_source = 'prompt' then
    insert into public.consent_log (user_id, kind, granted, policy_version, source)
    values (v_user, 'ai_processing', p_allowed, private.current_privacy_version(), p_source);
  end if;
end;
$$;
revoke execute on function public.set_ai_consent(boolean, text) from public, anon;
grant execute on function public.set_ai_consent(boolean, text) to authenticated;

-- Nothing is queued for the AI provider without consent. Named so it fires before the
-- quota and spend-cap triggers (triggers run in name order), so a refused request never
-- counts against the student's limits.
create or replace function private.require_ai_consent()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if not coalesce(
    (select p.ai_processing_allowed from public.profiles p where p.id = new.user_id), false
  ) then
    raise exception 'Allow StudyPulse to send this to Anthropic, our AI provider, to continue.'
      using errcode = 'SPA15', hint = 'ai_consent_required';
  end if;
  return new;
end;
$$;
revoke execute on function private.require_ai_consent() from public, anon, authenticated;

create trigger syllabus_uploads_00_require_ai_consent
before insert on public.syllabus_uploads
for each row execute function private.require_ai_consent();
create trigger card_generations_00_require_ai_consent
before insert on public.card_generations
for each row execute function private.require_ai_consent();

-- get_settings also returns the AI choice (same as 20260924006800 plus one field).
create or replace function public.get_settings()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  return (
    select jsonb_build_object(
      'profile', jsonb_build_object(
        'display_name', p.display_name,
        'school', p.school,
        'timezone', p.timezone,
        'daily_study_minutes', p.daily_study_minutes,
        'study_start_time', to_char(p.study_start_time, 'HH24:MI'),
        'card_tasks_enabled', p.card_tasks_enabled,
        'plan_tier', p.plan_tier,
        'onboarded_at', p.onboarded_at,
        'analytics_allowed', p.analytics_allowed,
        'error_reports_allowed', p.error_reports_allowed,
        'ai_processing_allowed', p.ai_processing_allowed
      ),
      'notifications', (
        select jsonb_build_object(
          'push_enabled', n.push_enabled,
          'email_digest_enabled', n.email_digest_enabled,
          'marketing_emails', n.marketing_emails,
          'remind_24h', n.remind_24h,
          'remind_2h', n.remind_2h,
          'exam_countdown', n.exam_countdown,
          'morning_digest', n.morning_digest,
          'morning_digest_time', to_char(n.morning_digest_time, 'HH24:MI'),
          'quiet_hours_enabled', n.quiet_hours_enabled,
          'quiet_hours_start', to_char(n.quiet_hours_start, 'HH24:MI'),
          'quiet_hours_end', to_char(n.quiet_hours_end, 'HH24:MI'),
          'daily_cap', n.daily_cap
        )
        from public.notification_prefs n where n.user_id = v_user
      ),
      -- Devices that can receive reminders, so the screen can say where they go.
      'devices', jsonb_build_object(
        'mobile', (select count(*) from public.notification_tokens t
                   where t.user_id = v_user and t.provider = 'expo' and t.invalidated_at is null),
        'web', (select count(*) from public.notification_tokens t
                where t.user_id = v_user and t.provider = 'web_push' and t.invalidated_at is null)
      )
    )
    from public.profiles p
    where p.id = v_user
  );
end;
$$;

-- ==== 20261110000100_study_sets_notes.sql
-- Study: card sets, spaced review, and notes.
--
-- - card_sets groups flashcards inside a course ("Chapter 5 vocabulary"). A card keeps its
--   course_id and references its set together with that course, so a card can only sit in
--   a set of its own course and ownership still follows the course (rule 5).
-- - Each card carries its own review state (when it's next due, how well it's known). Cards
--   belong to one student, so the state lives on the card.
-- - notes holds the student's class notes, per course.
-- Everything is owner-only through RLS, bounded per course, and deleted with the course.

-- card_sets ---------------------------------------------------------------------

create table public.card_sets (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  title text not null check (char_length(trim(title)) between 1 and 120),
  description text check (description is null or char_length(description) <= 500),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint card_sets_id_course_key unique (id, course_id)
);

create index card_sets_course_idx on public.card_sets (course_id, updated_at desc);

create trigger card_sets_set_updated_at before update on public.card_sets
for each row execute function public.set_updated_at();

-- At most 200 sets per course.
create or replace function private.limit_card_sets()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.card_sets where course_id = new.course_id) >= 200 then
    raise exception 'A course can have at most 200 card sets' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke execute on function private.limit_card_sets() from public, anon, authenticated;
create trigger card_sets_limit before insert on public.card_sets
for each row execute function private.limit_card_sets();

alter table public.card_sets enable row level security;

create policy "Users can view card sets in their courses"
on public.card_sets for select to authenticated
using ((select private.owns_course(course_id)));

create policy "Users can create card sets in their courses"
on public.card_sets for insert to authenticated
with check ((select private.owns_course(course_id)));

create policy "Users can update card sets in their courses"
on public.card_sets for update to authenticated
using ((select private.owns_course(course_id)))
with check ((select private.owns_course(course_id)));

create policy "Users can delete card sets in their courses"
on public.card_sets for delete to authenticated
using ((select private.owns_course(course_id)));

revoke all on public.card_sets from anon;

-- flashcards: a set, an order, a star, and review state ------------------------------

alter table public.flashcards
  add column set_id uuid,
  add column position integer not null default 0 check (position >= 0),
  add column starred boolean not null default false,
  -- Review state. due_at is null until the card is first studied ("new").
  add column due_at timestamptz,
  add column interval_days integer not null default 0 check (interval_days between 0 and 36500),
  add column ease numeric(3, 2) not null default 2.50 check (ease between 1.30 and 3.00),
  add column reps integer not null default 0 check (reps >= 0),
  add column lapses integer not null default 0 check (lapses >= 0),
  add column last_reviewed_at timestamptz;

-- Cards made before sets existed came from notes; they go into one set per course.
insert into public.card_sets (course_id, title)
select distinct f.course_id, 'Cards from notes'
from public.flashcards f;

update public.flashcards f
set set_id = s.id
from public.card_sets s
where s.course_id = f.course_id and f.set_id is null;

with ordered as (
  select id, row_number() over (partition by set_id order by created_at, id) - 1 as pos
  from public.flashcards
)
update public.flashcards f
set position = o.pos
from ordered o
where o.id = f.id;

alter table public.flashcards alter column set_id set not null;
alter table public.flashcards
  add constraint flashcards_set_fkey foreign key (set_id, course_id)
  references public.card_sets (id, course_id) on delete cascade;

create index flashcards_set_idx on public.flashcards (set_id, position);
create index flashcards_due_idx on public.flashcards (course_id, due_at);

-- At most 1,000 cards per set (ten pages of 100, the most a client reads).
create or replace function private.limit_flashcards()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.flashcards where set_id = new.set_id) >= 1000 then
    raise exception 'A card set can have at most 1,000 cards' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke execute on function private.limit_flashcards() from public, anon, authenticated;
create trigger flashcards_limit before insert on public.flashcards
for each row execute function private.limit_flashcards();

-- notes ---------------------------------------------------------------------------

create table public.notes (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  -- An empty title shows as "Untitled note".
  title text not null default '' check (char_length(title) <= 200),
  body text not null default '' check (char_length(body) <= 100000),
  pinned boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index notes_course_idx on public.notes (course_id, updated_at desc);

create trigger notes_set_updated_at before update on public.notes
for each row execute function public.set_updated_at();

-- At most 500 notes per course.
create or replace function private.limit_notes()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if (select count(*) from public.notes where course_id = new.course_id) >= 500 then
    raise exception 'A course can have at most 500 notes' using errcode = '23514';
  end if;
  return new;
end;
$$;
revoke execute on function private.limit_notes() from public, anon, authenticated;
create trigger notes_limit before insert on public.notes
for each row execute function private.limit_notes();

alter table public.notes enable row level security;

create policy "Users can view notes in their courses"
on public.notes for select to authenticated
using ((select private.owns_course(course_id)));

create policy "Users can create notes in their courses"
on public.notes for insert to authenticated
with check ((select private.owns_course(course_id)));

create policy "Users can update notes in their courses"
on public.notes for update to authenticated
using ((select private.owns_course(course_id)))
with check ((select private.owns_course(course_id)));

create policy "Users can delete notes in their courses"
on public.notes for delete to authenticated
using ((select private.owns_course(course_id)));

revoke all on public.notes from anon;

-- The Study screen in one call ------------------------------------------------------
-- Courses (for the pickers), every set with its card counts, the most recent notes with
-- a short excerpt (never the whole body), and how many cards were reviewed today in the
-- student's timezone. Runs as the caller, so RLS applies to every row it reads.
create or replace function public.get_study_overview()
returns jsonb
language plpgsql
stable
set search_path = ''
as $$
declare
  v_user uuid := (select auth.uid());
  v_timezone text;
  v_day_start timestamptz;
begin
  if v_user is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  select coalesce(p.timezone, 'UTC') into v_timezone from public.profiles p where p.id = v_user;
  v_timezone := coalesce(v_timezone, 'UTC');
  v_day_start := date_trunc('day', now() at time zone v_timezone) at time zone v_timezone;

  return jsonb_build_object(
    'timezone', v_timezone,
    'reviewed_today', (
      select count(*)
      from public.flashcards f
      join public.courses c on c.id = f.course_id and c.archived_at is null
      where f.last_reviewed_at >= v_day_start
    ),
    'courses', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', c.id, 'name', c.name, 'code', c.code, 'color', c.color
      ) order by coalesce(c.code, c.name), c.id)
      from public.courses c
      where c.archived_at is null
    ), '[]'::jsonb),
    'sets', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', s.id,
        'course_id', s.course_id,
        'title', s.title,
        'description', s.description,
        'updated_at', s.updated_at,
        'cards', n.cards,
        'due', n.due,
        'fresh', n.fresh,
        'starred', n.starred
      ) order by s.updated_at desc, s.id)
      from public.card_sets s
      join public.courses c on c.id = s.course_id and c.archived_at is null
      cross join lateral (
        select
          count(*) as cards,
          count(*) filter (where f.due_at <= now()) as due,
          count(*) filter (where f.due_at is null) as fresh,
          count(*) filter (where f.starred) as starred
        from public.flashcards f
        where f.set_id = s.id
      ) n
    ), '[]'::jsonb),
    'notes', coalesce((
      select jsonb_agg(x.note order by x.pinned desc, x.updated_at desc, x.id)
      from (
        select
          n.id, n.pinned, n.updated_at,
          jsonb_build_object(
            'id', n.id,
            'course_id', n.course_id,
            'title', n.title,
            'excerpt', left(regexp_replace(left(n.body, 600), '\s+', ' ', 'g'), 200),
            'pinned', n.pinned,
            'updated_at', n.updated_at
          ) as note
        from public.notes n
        join public.courses c on c.id = n.course_id and c.archived_at is null
        order by n.pinned desc, n.updated_at desc, n.id
        limit 200
      ) x
    ), '[]'::jsonb)
  );
end;
$$;

revoke execute on function public.get_study_overview() from public, anon;
